 queue<pair<int,int>> q;
 for(int r=0;r<10;r++)for(int c=0;c<10;c++)if(grid[r][c]=='B'){distance[r][c]=0;q.push({r,c});}
 const int dr[4]={-1,1,0,0},dc[4]={0,0,-1,1};
 while(!q.empty()){
  auto [r,c]=q.front();q.pop();
  if(grid[r][c]=='L'){out<<distance[r][c]-1<<'\n';return 0;}
  for(int k=0;k<4;k++){
   int rr=r+dr[k],cc=c+dc[k];
   if(rr>=0&&rr<10&&cc>=0&&cc<10&&grid[rr][cc]!='R'&&distance[rr][cc]==-1){
    distance[rr][cc]=distance[r][c]+1;q.push({rr,cc});
   }
  }
 }
}
