#include <fstream>
#include <queue>
#include <vector>
using namespace std;
int main(){
 ifstream in("factory.in");ofstream out("factory.out");int n;in>>n;
 vector<vector<int>> graph(n);for(int k=0;k<n-1;k++){int a,b;in>>a>>b;graph[a-1].push_back(b-1);}
 vector<int> counts(n,0);
 for(int start=0;start<n;start++){
  vector<bool> seen(n,false);queue<int> q;q.push(start);seen[start]=true;
  while(!q.empty()){
   int v=q.front();q.pop();counts[v]++;
   for(int w:graph[v])if(!seen[w]){seen[w]=true;q.push(w);}
  }
 }
 for(int v=0;v<n;v++)if(counts[v]==n){out<<v+1<<'\n';return 0;}
 out<<-1<<'\n';
}
