  int k;in>>k;for(int j=0;j<k;j++){string f;in>>f;carrier[f]|=(uint32_t{1}<<i);}
 }
 vector<uint32_t> masks;for(const auto& item:carrier)masks.push_back(item.second);
 for(size_t i=0;i<masks.size();i++)for(size_t j=i+1;j<masks.size();j++){
  uint32_t x=masks[i],y=masks[j];
  if((x&y)!=0 && (x&~y)!=0 && (y&~x)!=0){out<<"no\n";return 0;}
 }
